-- Survey trip tracking and survey expenses. PostgreSQL equivalent of SQL Server script 020.
BEGIN;
ALTER TABLE "Surveys" ADD COLUMN IF NOT EXISTS "ConductedByEmployeeId" uuid NULL REFERENCES "Employees"("Id");
ALTER TABLE "Surveys" ADD COLUMN IF NOT EXISTS "DistanceKm" numeric(10,2) NULL;
ALTER TABLE "Surveys" ADD COLUMN IF NOT EXISTS "IsPaused" boolean NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS "SurveyTimeEvents" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "SurveyId" uuid NOT NULL REFERENCES "Surveys"("Id") ON DELETE CASCADE, "Type" varchar(20) NOT NULL, "OccurredAtUtc" timestamp with time zone NOT NULL, "Reason" varchar(500) NULL, "RecordedBy" varchar(254) NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_SurveyTimeEvents_Id" ON "SurveyTimeEvents"("Id");
CREATE INDEX IF NOT EXISTS "IX_SurveyTimeEvents_SurveyId_SerialNo" ON "SurveyTimeEvents"("SurveyId","SerialNo");
CREATE INDEX IF NOT EXISTS "IX_SurveyTimeEvents_TenantId" ON "SurveyTimeEvents"("TenantId");
CREATE TABLE IF NOT EXISTS "SurveyExpenses" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "SurveyId" uuid NOT NULL REFERENCES "Surveys"("Id") ON DELETE CASCADE, "Category" varchar(30) NOT NULL, "Amount" numeric(18,2) NOT NULL, "Currency" varchar(3) NOT NULL, "IncurredAtUtc" timestamp with time zone NOT NULL, "PaidByEmployeeId" uuid NULL REFERENCES "Employees"("Id"), "Notes" varchar(500) NULL, "CreatedAtUtc" timestamp with time zone NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_SurveyExpenses_Id" ON "SurveyExpenses"("Id");
CREATE INDEX IF NOT EXISTS "IX_SurveyExpenses_SurveyId_SerialNo" ON "SurveyExpenses"("SurveyId","SerialNo");
CREATE INDEX IF NOT EXISTS "IX_SurveyExpenses_TenantId" ON "SurveyExpenses"("TenantId");
COMMIT;
